        row=[]
        for c in range(n):
            x=(c-r)%n
            if x in known: v=known[x]
            else:
                # repeat the ordered diagonal color pattern using nearest prior seed
                k=max((a for a in keys if a<x), default=keys[-1])
                v=known[k]
            row.append(v)
        out.append(row)
    return out

